plugins {
    alias(libs.plugins.android.library)
    alias(libs.plugins.kotlin.compose)
    `maven-publish`
}

// Gabarit's components for Jetpack Compose, from SkollN's design (the reference), as GabaritApple draws them on the
// iPhone. The tokens (GTokens.kt, GText.kt, GSymbols.kt) are generated by tools/tokens.py.
android {
    namespace = "com.masmarino.gabarit"
    compileSdk = 37
    defaultConfig { minSdk = 31 }
    buildFeatures { compose = true }
    testOptions { unitTests { isIncludeAndroidResources = true } }
    publishing { singleVariant("release") { withSourcesJar() } }
    // Java 17 bytecode, whatever JDK builds it (JitPack's, a developer's).
    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
}

kotlin { compilerOptions { jvmTarget.set(org.jetbrains.kotlin.gradle.dsl.JvmTarget.JVM_17) } }

dependencies {
    api(platform(libs.compose.bom))
    api(libs.compose.ui)
    api(libs.compose.foundation)
    api(libs.compose.material3)
    api(libs.compose.ui.tooling.preview)
    implementation(libs.androidx.activity.compose)
    debugImplementation(libs.compose.ui.tooling)
    testImplementation(libs.junit)
    testImplementation(libs.robolectric)
    testImplementation(libs.androidx.activity.compose)
}

// JitPack builds the tag and gives it as com.github.Masmarino:Gabarit:<tag>.
publishing {
    publications {
        register<MavenPublication>("release") {
            groupId = "com.github.Masmarino"
            artifactId = "gabarit"
            version = providers.environmentVariable("VERSION").getOrElse("local")
            afterEvaluate { from(components["release"]) }
        }
    }
}
